export const REPORT_TYPES={quote:{label:'Customer quote only',material:false,views:false,panels:false,measurements:false},material:{label:'Quote + material list',material:true,views:false,panels:false,measurements:true},views:{label:'Quote + 3D renderings',material:false,views:true,panels:false,measurements:true},panels:{label:'Quote + panel layout',material:true,views:true,panels:true,measurements:true},full:{label:'Full project report',material:true,views:true,panels:true,measurements:true}};
const escape=s=>String(s??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>Number(value||0).toLocaleString('en-US',{style:'currency',currency:'USD'});
const number=(value,digits=1)=>Number(value||0).toLocaleString('en-US',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const feet=value=>{const inches=Math.round(Number(value||0)*12);return `${Math.floor(inches/12)}′ ${inches%12}″`};

export function quoteTotals(state,summary,edgeTotals){
 const rows=[];
 if(state.quote.materialPricePerSqFt>0)rows.push({description:`${state.materials.panelType} panel material`,detail:`${number(summary.orderArea)} sq ft ordered blank area`,amount:summary.orderArea*state.quote.materialPricePerSqFt});
 for(const type of ['Ridge','Hip','Valley','Rake','Eave']){const length=edgeTotals[type]||0,rate=state.quote.trimPrices[type]||0;if(length>0&&rate>0)rows.push({description:`${type} trim / flashing`,detail:`${number(length)} linear ft`,amount:length*rate})}
 for(const item of state.quote.accessories)rows.push({description:item.description,detail:`${number(item.quantity,2)} × ${money(item.unitPrice)}`,amount:item.quantity*item.unitPrice});
 const subtotal=rows.reduce((sum,row)=>sum+row.amount,0),tax=subtotal*state.quote.taxRate/100;
 return {rows,subtotal,tax,total:subtotal+tax};
}

export function buildReportHtml({state,summary,edgeTotals,cutGroups,images=[],reportType='full'}){
 const option=REPORT_TYPES[reportType]||REPORT_TYPES.full,totals=quoteTotals(state,summary,edgeTotals),edgeTypes=['Ridge','Hip','Valley','Rake','Eave'];
 const address=state.address||'Address not entered',title=state.quote.projectName||'Roofing project',date=state.quote.date||new Date().toISOString().slice(0,10);
 const estimateRows=totals.rows.length?totals.rows.map(row=>`<tr><td>${escape(row.description)}</td><td>${escape(row.detail)}</td><td class="money">${money(row.amount)}</td></tr>`).join(''):'<tr><td colspan="3">Pricing has not been entered. Quantities remain available for estimating.</td></tr>';
 const measurements=option.measurements?`<section><h2>Roof measurements</h2><div class="cards"><div><span>Plan area</span><b>${number(summary.flat)} ft²</b></div><div><span>Sloped area</span><b>${number(summary.surface)} ft²</b></div><div><span>Roof squares</span><b>${number(summary.surface/100,2)}</b></div><div><span>Roof planes</span><b>${state.faces.length}</b></div></div><h3>Roof-edge totals</h3><table><thead><tr>${edgeTypes.map(type=>`<th>${type}</th>`).join('')}</tr></thead><tbody><tr>${edgeTypes.map(type=>`<td>${feet(edgeTotals[type]||0)}</td>`).join('')}</tr></tbody></table></section>`:'';
 const materials=option.material?`<section><h2>Material and cut summary</h2><p><b>${escape(state.materials.panelType)}</b> · ${escape(state.materials.gauge)} · ${escape(state.settings.width)}″ effective coverage · ${escape(state.settings.allowance)}″ total end allowance</p><div class="cards"><div><span>Panels</span><b>${summary.count}</b></div><div><span>Longest cut</span><b>${feet(summary.longest)}</b></div><div><span>Blank material</span><b>${number(summary.orderArea)} ft²</b></div><div><span>Overlength</span><b>${summary.oversize}</b></div></div><table><thead><tr><th>Roof plane</th><th>Panel length</th><th>Quantity</th><th>Status</th></tr></thead><tbody>${cutGroups.map(row=>`<tr><td>${escape(row.name)}</td><td>${feet(row.length)}</td><td>${row.qty}</td><td>${row.oversize?'Exceeds entered maximum':'Field verify'}</td></tr>`).join('')||'<tr><td colspan="4">No panel cuts calculated.</td></tr>'}</tbody></table></section>`:'';
 const renders=option.views&&images.length?`<section class="page-break"><h2>${option.panels?'3D roof and calculated panel layout':'3D roof views'}</h2><div class="renders">${images.map(image=>`<figure><img src="${image.data}" alt="${escape(image.label)}"><figcaption>${escape(image.label)}</figcaption></figure>`).join('')}</div></section>`:'';
 return `<!doctype html><html><head><meta charset="utf-8"><title>${escape(title)} — Taylor Metal Quote</title><style>@page{size:letter;margin:.55in}*{box-sizing:border-box}body{font:12px/1.45 Arial,sans-serif;color:#173043;margin:0}header{display:flex;justify-content:space-between;border-bottom:5px solid #1aaed9;padding-bottom:16px;margin-bottom:22px}.brand{font-size:24px;font-weight:800;color:#09273a}.brand small{display:block;font-size:10px;letter-spacing:.18em;color:#39728c}.meta{text-align:right}h1{font-size:25px;margin:0 0 4px}h2{font-size:17px;color:#0b6688;border-bottom:1px solid #acd6e5;padding-bottom:5px;margin:22px 0 10px}h3{font-size:13px;margin:16px 0 6px}.customer{display:grid;grid-template-columns:1fr 1fr;gap:20px}.customer p{margin:3px 0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.cards div{border:1px solid #b8d2dd;background:#f2f8fa;padding:9px}.cards span{display:block;color:#587587;font-size:10px;text-transform:uppercase}.cards b{font-size:14px}table{width:100%;border-collapse:collapse;margin-top:8px}th,td{padding:7px;border-bottom:1px solid #c9dce4;text-align:left}th{background:#e7f4f8;color:#164e67}.money{text-align:right}.totals{width:290px;margin:10px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:5px}.totals .grand{font-size:16px;font-weight:bold;border-top:2px solid #1aaed9}.renders{display:grid;grid-template-columns:1fr 1fr;gap:12px}.renders figure{margin:0;border:1px solid #b7cfda;padding:6px;break-inside:avoid}.renders img{display:block;width:100%;background:#0a2032}.renders figcaption{text-align:center;font-weight:bold;padding:5px}.notice{margin-top:25px;padding:10px;border-left:4px solid #d49a1f;background:#fff7df;font-size:10px}.notes{white-space:pre-wrap}.page-break{break-before:page}@media print{.page-break{break-before:page}}</style></head><body><header><div class="brand"><small>TAYLOR METAL PRODUCTS</small>Roof Planner</div><div class="meta"><b>${escape(state.quote.number?'Quote '+state.quote.number:'Customer estimate')}</b><br>${escape(date)}${state.quote.validUntil?`<br>Valid through ${escape(state.quote.validUntil)}`:''}</div></header><h1>${escape(title)}</h1><p>${escape(address)}</p><div class="customer"><div><h2>Prepared for</h2><p><b>${escape(state.customer.name||'Customer')}</b></p><p>${escape(state.customer.company)}</p><p>${escape(state.customer.phone)}</p><p>${escape(state.customer.email)}</p></div><div><h2>Roof system</h2><p><b>${escape(state.materials.panelType)}</b></p><p>${escape(state.materials.gauge)} · ${escape(state.settings.width)}″ coverage</p><p>Selected color: <span style="display:inline-block;width:10px;height:10px;background:${escape(state.settings.color)};border:1px solid #666"></span> ${escape(state.settings.color)}</p></div></div>${measurements}<section><h2>Estimate</h2><table><thead><tr><th>Item</th><th>Quantity / basis</th><th class="money">Amount</th></tr></thead><tbody>${estimateRows}</tbody></table><div class="totals"><div><span>Subtotal</span><b>${money(totals.subtotal)}</b></div><div><span>Tax (${number(state.quote.taxRate,2)}%)</span><b>${money(totals.tax)}</b></div><div class="grand"><span>Total</span><b>${money(totals.total)}</b></div></div></section>${materials}${renders}${state.quote.notes?`<section><h2>Notes</h2><div class="notes">${escape(state.quote.notes)}</div></section>`:''}<p class="notice"><b>Estimate notice:</b> Aerial measurements, panel quantities, cut lengths, trim totals, and pricing must be verified against field measurements, manufacturer requirements, and fabricator review before ordering. Panel blanks are conservative estimates; offcut nesting and engineered laps are not included.</p></body></html>`;
}
